select n.nspname||'.'||c.relname as tabla, p.polname, p.polcmd, array_to_string(array(select rolname from pg_roles where oid = any(p.polroles)), ',') as roles, pg_get_expr(p.polqual, p.polrelid) as using_expr, pg_get_expr(p.polwithcheck, p.polrelid) as check_expr from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('crm','private','public') order by 1,2
